#include <DHT.h>

#define DHT_PIN 2 // Pin where the DHT22 sensor is connected

DHT dht(DHT_PIN, DHT22); // Initialize the DHT22 sensor

void setup() {
  Serial.begin(9600); // Initialize the serial communication
  delay(2000); // Delay to let the sensor settle
}

void loop() {
  float temperature, humidity;

  // Get the temperature and humidity from the sensor
  int16_t rawtemperature = dht.readTemperature();
  int16_t rawhumidity = dht.readHumidity();

  // Check if the sensor is calibrated correctly
  if (isnan(temperature) || isnan(humidity)) {
    Serial.println("Failed to read from DHT sensor!");
    return;
  }

  // Convert raw data to temperature and humidity values
  temperature = dht.computeTemperature( rawtemperature );
  humidity = dht.computeHumidity( rawhumidity );

  // Print the temperature and humidity values
  Serial.print("Temperature (°C): ");
  Serial.println(temperature);
  Serial.print("Humidity (%): ");
  Serial.println(humidity);

  delay(5000); // Wait 5 seconds before taking the next reading
}
