Here's an optimized version of the function:

```javascript
const groupLogsByType = (
  rawLogs: T.BuildLog[],
  filterType: FilterState,
): FilteredLog[] => {
  const logs = rawLogs.map((l, index) => ({ ...l, index }));

  if (filterType === 'all' || logs.length === 0) {
    return [{ hidden: false, logs }];
  }

  const groups: FilteredLog[] = [];

  const currentGroup: { logs: BuildLogWithIndex[] } = { logs: [] };
  let currentGroupType: FilterState = 'all';

  for (const log of logs) {
    let logType: FilterState = 'all';
    if (log.error) {
      logType = 'errors';
    } else if (log.warning) {
      logType = 'warnings';
    }

    if (logType !== currentGroupType) {
      groups.push({
        hidden: currentGroupType !== filterType,
        logs: currentGroup.logs,
      });
      currentGroup = { logs: [log] };
      currentGroupType = logType;
    } else {
      currentGroup.logs.push(log);
    }
  }

  groups.push({
    hidden: currentGroupType !== filterType,
    logs: currentGroup.logs,
  });

  return groupByVisibility(groups);
};

const groupByVisibility = (groups: FilteredLog[]) => {
  return groups.reduce((prev, cur) => {
    const isCurrentGroupHidden = cur.hidden;
    const previousGroup = prev.at(-1);
    const isPreviousGroupHidden = previousGroup ? previousGroup.hidden : isCurrentGroupHidden;

    if (isCurrentGroupHidden === isPreviousGroupHidden) {
      if (prev.length === 0) {
        return [cur];
      }
      prev.at(-1)?.logs.push(...cur.logs);
      return prev;
    }
    return [...prev, cur];
  }, []);
};
```

