  const [feedbackData, setFeedbackData] = useState({
    name: '',
    email: '',
    comments: '',
  });

  const { handleSubmitFeedback } = useContext(FeedbackContext);

  const handleInputChange = (event) => {
    setFeedbackData((prevData) => ({ ...prevData, [event.target.name]: event.target.value }));
