  const page = pages[0];
  const content = page.content;
  const cursorWidth = 16; // Default cursor width
  const cursorHeight = 16; // Default cursor height
  const cursorX = page.clientX + page.scrollX + 10; // Adjust cursor position
  const cursorY = page.clientY + page.scrollY + 10; // Adjust cursor position

  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  canvas.width = page.width;
  canvas.height = page.height;

