                client.Credentials = new NetworkCredential(_emailAccounts[_currentAccountIndex], _emailPasswords[_currentAccountIndex]);
                client.Send(mail);
            }

            // Rotate to the next email account
            _currentAccountIndex = (_currentAccountIndex + 1) % _emailAccounts.Length;
        }
    }
}
